  (* [comment removed for export] *)
  Lemma ci_NG : forall regs m (pr : Z),
    rdn SEGS m (Z_to_bv 64 0x38470) 8 = Some (Z_to_le_bytes 8 0x394e0) -> rdn SEGS m (Z_to_bv 64 0x394e0) 4 = Some (Z_to_le_bytes 4 3) ->
    (1 <= pr < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 pr -> getr regs 11 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x1bc14 : word) m rom) (mkst regs' (0x1bd74 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 0x11001 /\ getr regs' 11 = Z_to_bv 64 0x10fef
      /\ regs_agree (fun x => In x [10; 11]%list) regs regs'.
Proof.
