  (* [comment removed for export] *)
  Lemma ci_B1 : forall regs m (s pr pg pb : Z) (vr vg vb : pixv),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pr)%Z -> (1 <= pg)%Z -> (1 <= pb)%Z -> PIXat m pr vr -> PIXat m pg vg -> PIXat m pb vb ->
    (pr + 64 <= s - 80)%Z -> (pg + 64 <= s - 80)%Z -> (pb + 64 <= s - 80)%Z ->
    p_w vg = p_w vr -> p_h vg = p_h vr -> p_d vg = p_d vr -> p_w vb = p_w vr -> p_h vb = p_h vr -> p_d vb = p_d vr -> p_d vr = 8%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 pr -> getr regs 11 = Z_to_bv 64 pg -> getr regs 12 = Z_to_bv 64 pb ->
    exists regs',
      msteps SEGS (mkst regs (0x1bc14 : word) m rom) (mkst regs' (0x1bc68 : word) (DIM9 m s (p_w vr) (p_h vr)) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 19 = Z_to_bv 64 pr /\ getr regs' 9 = Z_to_bv 64 pg /\ getr regs' 18 = Z_to_bv 64 pg /\ getr regs' 8 = Z_to_bv 64 pb
      /\ regs_agree (fun x => In x [1; 8; 9; 10; 11; 12; 13; 14; 18; 19]%list) regs regs'.
Proof.
