  Lemma ci_B2 : forall regs m (s w h : Z),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= w < 2 ^ 31)%Z -> (0 <= h < 2 ^ 31)%Z -> cri_cells m s w h ->
    getr regs 2 = Z_to_bv 64 (s - 80) ->
    exists regs',
      msteps SEGS (mkst regs (0x1bc68 : word) m rom) (mkst regs' (0x18f24 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 1 = Z_to_bv 64 0x1bcb8
      /\ getr regs' 10 = Z_to_bv 64 w /\ getr regs' 11 = Z_to_bv 64 h /\ getr regs' 12 = Z_to_bv 64 32
      /\ regs_agree (fun x => In x [1; 10; 11; 12]%list) regs regs'.
