  (* [comment removed for export] *)
  Lemma ci_E : forall regs r0 m (s pixd : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> cellsZ m (frame5 s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 18 = Z_to_bv 64 pixd ->
    exists regs',
      msteps SEGS (mkst regs (0x1bcf8 : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 pixd
      /\ (forall x, In x [8; 9; 18; 19]%bv -> getr regs' x = getr r0 x)
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 18; 19]%list) regs regs'.
Proof.
